typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    qsort(A, N, sizeof(ll), cmp_ll);

    ll ans = (1LL << 60);

    for (int l = 0; l < N; ) {
        int r = l;
        while (r < N && A[r] == A[l]) r++;

        ll x = A[l];
        ll cnt = r - l;

        ll cur = cnt;
        ll y = x;
        while (y > 0) {
            cur += y % 10;
            y /= 10;
        }

        if (cur < ans) ans = cur;
        l = r;
    }

    printf("%lld\n", ans);
    free(A);
    return 0;
}

