import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        final int MAXD = 16; // enough for Ai up to 1e15 and sum up to around 1e16
        long[] cnt = new long[MAXD + 1];

        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            int d = 0;
            while (x > 0) {
                cnt[d] += x % 10;
                x /= 10;
                d++;
            }
        }

        long answer = Long.MAX_VALUE;
        long carry = 0;
        long prefixDigitSum = 0;

        for (int k = 0; k <= MAXD; k++) {
            long cur = cnt[k] + carry;
            carry = cur / 10;
            long digit = cur % 10;
            prefixDigitSum += digit;

            // If we choose a subset whose total is divisible by 10^(k+1),
            // then modulo 10^(k+1), the removed sum must equal current prefix.
            // The minimum digit sum of such removed amount is prefixDigitSum.
            // So achievable minimum is total digit sum - prefixDigitSum + 1
            // (+1 because we must buy at least one item, and removing all items is not allowed).
            answer = Math.min(answer, prefixDigitSum);
        }

        // Total digit sum of all prices
        long totalDigitSum = 0;
        carry = 0;
        for (int k = 0; k <= MAXD; k++) {
            long cur = cnt[k] + carry;
            carry = cur / 10;
            totalDigitSum += cur % 10;
        }
        while (carry > 0) {
            totalDigitSum += carry % 10;
            carry /= 10;
        }

        // answer currently stores minimum digit sum of a positive amount X
        // such that S-X is a non-empty subset sum candidate via the decimal-carry argument.
        // Equivalent final formula:
        // min over k of digitSum(sum(Ai) mod 10^(k+1)), excluding choosing all items.
        // This is exactly answer, but we must also consider buying all items: digitSum(total sum).
        long totalSumDigit = totalDigitSum;
        long best = totalSumDigit;

        carry = 0;
        long pref = 0;
        for (int k = 0; k <= MAXD; k++) {
            long cur = cnt[k] + carry;
            carry = cur / 10;
            pref += cur % 10;
            best = Math.min(best, pref);
        }
        while (carry > 0) {
            pref += carry % 10;
            best = Math.min(best, pref);
            carry /= 10;
        }

        System.out.println(best);
    }
}

import sys

def digit_sum(x):
    return sum(int(d) for d in str(x))

def solve():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    a = list(map(int, input_data[1:]))

    if n <= 20:
        ans = float('inf')
        # enumerate all non-empty subsets
        for mask in range(1, 1 << n):
            total = 0
            for i in range(n):
                if mask >> i & 1:
                    total += a[i]
            ans = min(ans, digit_sum(total))
        print(ans)
        return

    # meet-in-the-middle for n > 20
    mid = n // 2
    left = a[:mid]
    right = a[mid:]

    def subset_sums(arr):
        res = []
        m = len(arr)
        for mask in range(1 << m):
            s = 0
            for i in range(m):
                if mask >> i & 1:
                    s += arr[i]
            res.append(s)
        return res

    left_sums = subset_sums(left)
    right_sums = subset_sums(right)

    # We want minimal digit_sum(total)
    # Brute force all pairs could be big, but we can try to find if any sum is a power of 10
    right_set = set(right_sums)
    ans = float('inf')

    # Check all sums from left_sums and right_sums individually (non-empty subsets)
    for s in left_sums:
        if s != 0:
            ans = min(ans, digit_sum(s))
    for s in right_sums:
        if s != 0:
            ans = min(ans, digit_sum(s))

    # Now check combined
    # Sort right_sums for binary search
    right_sums.sort()
    max_total = sum(a)
    max_pow10 = 1
    while max_pow10 <= max_total:
        max_pow10 *= 10

    # For each left sum, try to get digit sum 1,2,... by finding complement
    for s in left_sums:
        # try to make a power of 10
        pow10 = 10
        while pow10 <= max_total * 10:
            need = pow10 - s
            if need < 0:
                pow10 *= 10
                continue
            # binary search need in right_sums
            lo, hi = 0, len(right_sums)-1
            while lo <= hi:
                mid_idx = (lo + hi)//2
                if right_sums[mid_idx] == need:
                    ans = min(ans, digit_sum(pow10))
                    break
                elif right_sums[mid_idx] < need:
                    lo = mid_idx + 1
                else:
                    hi = mid_idx - 1
            pow10 *= 10

    # If still large, just compute all pairs (might be okay up to 2^20 each)
    if ans == float('inf'):
        # fallback: compute all combinations
        for ls in left_sums:
            for rs in right_sums:
                if ls + rs > 0:
                    ans = min(ans, digit_sum(ls + rs))
    print(ans)

if __name__ == "__main__":
    solve()
